INSERT INTO feature VALUES('context-stack','editor','The context stack','language-server','implemented','ordinary',NULL,'At a position, every application spine that encloses it, innermost first: its head, the type the judgement gives the head, the declared head and its arity, the slot the position fills, and the type the judgement checked the slot''s argument against, or owed where the judgement typed none there. The form store reads the spines of each form it joins off the molded tree, which holds the parser''s repairs, and keeps them with the form''s region, so an open call answers and a keystroke reads the spines of the forms it joins alone. Served as `gandr/stack`; signature help answers one signature per spine. The render bus sends the stack at the editor''s cursor as a card, which `gandr view` shows as a pane: the head, its type with the parameter the slot fills underlined, the slot over the arity, and the expected type.','surface-session surface-parser surface-dispatcher surface-lsp surface-render-remote surface-tui','crates/surface-session/src/stack.rs crates/surface-session/tests/forms.rs crates/surface-lsp/src/server.rs crates/surface-lsp/src/hub.rs crates/surface-tui/tests/captures.rs',NULL,'#6292');
